658			\omega^{-\tr(ej)} \ket{j}\;, \qquad
659			\ket{e_Z} = \ket{e}\;;
660		\]
661		the Fourier transform
662		\begin{equation}\label{eq:fourier-f}
663			F = \frac{1}{\sqrt{q}} \sum_{a, b \in \F_q}
664			\omega^{-\tr(ab)} \ket{a}\bra{b}
665		\end{equation}
666		maps the computational ($Z$) eigenbasis to the $X$ eigenbasis. We write
667		$\{\tau^W_e\}_{e \in \F_q}$ for the projective measurement whose elements
668		are the rank-one projectors onto the vectors of the $W$ eigenbasis. For
669		systems of $n$ qudits, we write, for $W \in \{X,Z\}$ and $a \in \F_q^n$,
670		\[
671			\tau^W(a) = \tau^W(a_1) \ot \dots \ot \tau^W(a_n)\;, \qquad
672			\ket{e_W} = \ket{(e_1)_W} \ot \dots \ot \ket{(e_n)_W}
673		\]
674		for $e \in \F_q^n$, with associated rank-one projectors $\tau^W_e$.
675		The distinction between the general prime-characteristic definitions and
676		the characteristic-two specializations used by the Pauli basis test is
677		documented in \cite{gap:qpbt_characteristic-two-pauli-scope}.
678	\end{definition}
